WITH valid AS (SELECT id, customer_id, store_id, order_date, status, channel, discount, shipping_fee, ROUND(discount / amount, 2) AS discount_per_amount, LOWER(channel) AS channel_lower, COALESCE(channel, 'NONE') AS channel_filled FROM orders WHERE store_id IS NOT NULL) SELECT DATE_TRUNC('YEAR', order_date) AS year_start, channel, COUNT(CASE WHEN status = 'RETURNED' THEN 1 END) AS returned_count, ROUND(AVG(discount_per_amount), 2) AS avg_discount_per_amount, APPROX_PERCENTILE(discount_per_amount, ARRAY(0.25, 0.5, 0.75)) AS discount_per_amount_quartiles, SORT_ARRAY(COLLECT_SET(status)) AS status_list, CORR(discount, shipping_fee) AS corr_discount_shipping_fee FROM valid GROUP BY DATE_TRUNC('YEAR', order_date), channel ORDER BY channel
